(7304364, 1139353, 156466, '<td valign="top">My favorite (so far at least).  Really well done.  Makes me wish I had vertical blinds to try it.</td>', 'My favorite (so far at least).  Really well done.  Makes me wish I had vertical blinds to try it.', '2015-01-20 11:42:23.000000', NULL, 1),
(7304365, 1139028, 156466, '<td valign="top">I could wish her a little more faded, but otherwise very nice.  And your model did a great job holding still - if not holding her breath completely. ;)</td>', 'I could wish her a little more faded, but otherwise very nice.  And your model did a great job holding still - if not holding her breath completely. ;)', '2015-01-20 11:43:15.000000', NULL, 1),
(7304367, 1139064, 156466, '<td valign="top">One more where I say, "Verticals need to be vertical".  Otherwise I like it a lot, but wish you''d also come a little closer and got rid of the door/jamb and the view downstairs.</td>', 'One more where I say, "Verticals need to be vertical".  Otherwise I like it a lot, but wish you''d also come a little closer and got rid of the door/jamb and the view downstairs.', '2015-01-20 11:45:08.000000', NULL, 1),
